def residual(x,update):
    if len(x)!=len(update):raise ValueError('shape mismatch')
    return [a+b for a,b in zip(x,update)]
assert residual([],[])==[]
print(residual([1,2,3],[0.5,-1,2]))

def causal(n):
    if n<0:raise ValueError('length')
    return [[int(key<=query) for key in range(n)] for query in range(n)]
assert causal(0)==[]
print(causal(3))

import math
def rotate(x,y,angle):
    return x*math.cos(angle)-y*math.sin(angle),x*math.sin(angle)+y*math.cos(angle)
x,y=rotate(1,0,math.pi/2)
assert abs(x*x+y*y-1)<1e-12
print(round(x,5),round(y,5))

def family(task):
    choices={'embedding':'encoder','continuation':'decoder','translation':'encoder-decoder'}
    if task not in choices:raise ValueError('unsupported task')
    return choices[task]
print([family(x) for x in ['embedding','continuation','translation']])

def fits(parts,reserve,limit):
    values=list(parts.values())+[reserve]
    if any(x<0 for x in values):raise ValueError('negative budget')
    return sum(values)<=limit
assert fits({},0,0)
print(fits({'instructions':100,'user':50,'evidence':700},200,1000))

def nucleus(items,p):
    if not 0<p<=1 or abs(sum(v for _,v in items)-1)>1e-9:raise ValueError('distribution')
    out=[];mass=0
    for name,prob in sorted(items,key=lambda x:(-x[1],x[0])):
        if prob<0:raise ValueError('negative probability')
        out.append(name);mass+=prob
        if mass>=p:break
    return out
print(nucleus([('a',0.6),('b',0.25),('c',0.15)],0.8))

def build_prompt(policy,task,source,source_limit=100):
    if len(source)>source_limit:raise ValueError('source too long')
    return {'policy':policy,'task':task,'untrusted_source':source}
p=build_prompt('Use only supplied evidence','Extract an ID','ID: A-7')
assert p['policy']=='Use only supplied evidence'
print(p['untrusted_source'])

def validate_call(payload):
    if set(payload)!={'tool','query'}:raise ValueError('fields')
    if payload['tool']!='lookup' or not isinstance(payload['query'],str) or not payload['query'].strip():
        raise ValueError('arguments')
    return payload['query'].strip()
